  // raw USB traffic via the USB‑to‑TTL adapter. The sketch below reads incoming bytes from the
  // host and stores printable characters.
  if (Serial.available()) {
    char c = Serial.read();
    if (c >= 32 && c <= 126) { // printable ASCII range
      if (idx < LOG_SIZE - 1) {
